// Four actual strand routings per site: two crossings and two turning pairs.
export function knotLayout(size,grid,width,variant){const rows=grid/2,cols=grid,R=(width-130)*.45,cx=width/2,cy=width/2,symbols=[],decor=[];
 const at=(row,col,x,y)=>{const a=2*Math.PI*(col+x)/cols,r=R*(.30+.70*(row+y)/rows)*(1+.055*Math.cos(5*a+variant*.8));return[cx+r*Math.cos(a),cy+r*Math.sin(a)*.96];};
 for(let row=0;row<rows;row++)for(let col=0;col<cols;col++){const point=(x,y)=>at(row,col,x,y),line=(a,b)=>Array.from({length:17},(_,i)=>point(a[0]+(b[0]-a[0])*i/16,a[1]+(b[1]-a[1])*i/16)),curve=(axis,opposite)=>Array.from({length:25},(_,i)=>{const t=i/24,b=.24*Math.sin(Math.PI*t);return axis?point(opposite?1-b:b,t):point(t,opposite?1-b:b);}),stroke=Math.min(R*.70/rows,R*.30*2*Math.PI/cols)*.19;
 symbols.push({stroke,center:point(.5,.5),cross:[point(.35,.35),point(.35,.65)],turns:[point(.5,.24),point(.24,.5)],render:v=>v<2?[{p:line([0,0],[1,1])},{p:line([0,1],[1,0])},{p:line(v?[.23,.77]:[.23,.23],v?[.77,.23]:[.77,.77]),white:true},{p:line(v?[0,1]:[0,0],v?[1,0]:[1,1])}]:[{p:curve(v===3,0)},{p:curve(v===3,1)}]});}
 return{kind:'knot',symbols,decor,stars:[],bounds:[cx-R*1.055,cy-R*1.055,cx+R*1.055,cy+R*1.055]};
}
export function knotSVG(layout,values,ink,paper,shapeOffset){const path=ps=>ps.map((p,i)=>`${i?'L':'M'}${p[0]} ${p[1]}`).join(' ');return layout.symbols.map((s,i)=>s.render(i*2===shapeOffset?2:(values[i*2]<<1)|values[i*2+1]).map(p=>`<path d="${path(p.p)}" fill="none" stroke="${p.white?paper:ink}" stroke-width="${s.stroke*(p.white?3.3:1)}" stroke-linecap="round"/>`).join('')).join('');}
export function readKnots(layout,at,shapeOffset,variant){const values=[],valid=[];layout.symbols.forEach((s,i)=>{if(i*2===shapeOffset){values.push((variant>>1)&1,variant&1);valid.push(true,true);return;}const center=at(s.center),cross=center.ink>.40,pair=(cross?s.cross:s.turns).map(at),low=cross?(pair[0].ink>pair[1].ink?0:1):(pair[0].ink>pair[1].ink?0:1),ok=center.inside&&pair.every(p=>p.inside)&&Math.abs(center.ink-.40)>.12&&Math.abs(pair[0].ink-pair[1].ink)>.20;values.push(cross?0:1,low);valid.push(ok,ok);});return{values,valid};}
